/**
 * 在主 App 中注册 App Intent：快捷指令可「打开 zheng://screenshot」，
 * 由 App 内读剪贴板 + 跳转财务页 + AI 自动记账（与深链一致）。
 * 修改请编辑本文件；勿直接改 ios 下生成文件（prebuild 会覆盖）。
 */
const { IOSConfig } = require('expo/config-plugins');

const SWIFT_SOURCE = `//
// ZhengAppIntents.swift
// Generated by plugins/with-zheng-app-intents.js
//

import AppIntents
import UIKit

@available(iOS 16.0, *)
struct ZhengScreenshotAutoLedgerIntent: AppIntent {
    static var title: LocalizedStringResource = "剪贴板截图记账"

    static var description = IntentDescription(
        "打开应用并从剪贴板读取截图，跳转财务页由 AI 自动记账（请先在快捷指令中复制截图）。"
    )

    static var openAppWhenRun: Bool = true

    @MainActor
    func perform() async throws -> some IntentResult {
        guard let url = URL(string: "zheng://screenshot") else {
            return .result(dialog: IntentDialog("无效链接。"))
        }
        await MainActor.run {
            UIApplication.shared.open(url, options: [:], completionHandler: nil)
        }
        return .result(dialog: IntentDialog("已打开应用，正在处理截图记账…"))
    }
}

@available(iOS 17.0, *)
struct ZhengAppShortcuts: AppShortcutsProvider {
    static var appShortcuts: [AppShortcut] {
        AppShortcut(
            intent: ZhengScreenshotAutoLedgerIntent(),
            phrases: [
                "在\\(.applicationName)里截图记账",
                "\\(.applicationName)截图记账",
            ],
            shortTitle: "截图记账",
            systemImageName: "creditcard.and.scribble"
        )
    }
}
`;

/** @type {import('expo/config-plugins').ConfigPlugin} */
function withZhengAppIntents(config) {
  return IOSConfig.XcodeProjectFile.withBuildSourceFile(config, {
    filePath: 'ZhengAppIntents.swift',
    contents: SWIFT_SOURCE,
    overwrite: true,
  });
}

module.exports = withZhengAppIntents;
